    def css_modifier
      'pages-header--slim' if @type == :slim
    end
  end
end

def edit
  @page = Page.find_or_initialize_by(
    name: params[:id],
    locale: params.require(:locale)
  )
end

def as_api_v2
  @api_v2 ||= ::Course::Richtext::APIV2.new(self).as_json # rubocop:disable Naming/MemoizedInstanceVariableName
end

def fields
  {
    id: object.id,
    text:,
  }
end

def initialize(context)
  @context = context
  @included = Set.new
  @meta = {}
  @links = {}
end

def data=(entity)
  @data = PrimaryData.from entity
end

def include!(*includes)
  @included.merge(includes.flat_map {|relation_name|
    @data.include(relation_name, @context)
  })
end

def meta!(key, value)
  @meta[key] = value
end

def link!(name, href)
  @links[name] = href
end

def serialize(context)
  included = @included
  meta = @meta
  links = @links

  {'data' => @data.serialize(context)}.tap {|hash|
    hash['included'] = included.map {|i| i.serialize(context) } unless included.empty?
    hash['meta'] = meta unless meta.empty?
    hash['links'] = links unless links.empty?
  }
}

